} else if (effectiveVisualizationType === ChartDisplayType.ActionsTable) {
    component = (
        <Table
            uniqueKey={props.uniqueKey}
            query={query}
            context={props.context}
            cachedResults={props.cachedResults as HogQLQueryResponse | undefined}
            embedded={props.embedded}
            onInspect={canDrill ? inspect : undefined}
        />

): AxisSeries<any>[] => {
    if (!response) {
        return []
    }

    return columns.map((col) => {
        const series = (tabularColumnSettings || []).find((n) => n?.name === col.name)

        return {
            column: col,
            data: [],
            settings: series?.settings ?? DefaultAxisSettings(),
        }
    })

if (column.column.type.isNumerical) {
    try {
        if (value === null) {
            const nullReplacement = showNullsAsZero ? 0 : null

            return {
                value: nullReplacement,
                formattedValue: formatDataWithSettings(nullReplacement, column.settings),
                type: column.column.type.name,
            }
        }

        const multiplier = column.settings?.formatting?.style === 'percent' ? 100 : 1

        if (
            column.settings?.formatting?.decimalPlaces != null &&
            column.settings.formatting.style !== 'short'
        ) {
            return {
                value,
                formattedValue: formatDataWithSettings(
                    parseFloat(
                        (parseFloat(value.toString()) * multiplier).toFixed(
                            column.settings.formatting.decimalPlaces
                        )
                    ),
                    column.settings
                ),
                type: column.column.type.name,
            }

return (
    <BindLogic logic={insightLogic} props={insightLogicProps}>
        <div className={clsx('ExportedInsight', isMetric && 'ExportedInsight--metric')}>
            {!noHeader && (
                <div className="ExportedInsight__header">
                    <div>
                        <h5>
                            <TopHeading query={query} />
                        </h5>
                        <h4 title={name} className="ExportedInsight__header__title">
                            {name || derived_name}
                        </h4>
                        {description && <div className="ExportedInsight__header-description">{description}</div>}
                    </div>

                    {!whitelabel && <Logo size="xs" className="shrink-0 ml-3" />}
                </div>
            )}
            {showWatermark && (
                <div className="ExportedInsight__watermark">
                    <Logo size="xs" />
                </div>
            )}
            <div
                className={clsx({
                    ExportedInsight__content: true,
                    'ExportedInsight__content--with-watermark': showWatermark,
                })}
            >
                <Query
                    query={insight.query}
                    cachedResults={insight}
                    readOnly
                    context={{ insightProps: insightLogicProps }}
                    embedded
                    inSharedMode
                />

MAX_WIDTH_PIXELS = 4000  # Max width for wide content like funnels with many steps
MAX_HEIGHT_PIXELS = 5000  # Prevents Chrome from consuming excessive memory on very tall pages
CONTENT_PADDING = 80  # Padding for card borders

REPLAY_WRAPPER_SELECTOR = ".replayer-wrapper"

# The replay player mounts rrweb either in the app document or inside its own same-origin frame
# document, and a document query never crosses into a frame, so look in both.
FIND_REPLAY_WRAPPER_JS = f"""(
    document.querySelector('{REPLAY_WRAPPER_SELECTOR}') ||
    document.querySelector('iframe.PlayerFrame__document')?.contentDocument?.querySelector('{REPLAY_WRAPPER_SELECTOR}')
)"""

MEASURE_CONTENT_HEIGHT_JS = f"""
    const element = document.querySelector('.InsightCard__viz') ||
                  document.querySelector('.ExportedInsight__content') ||
                  {FIND_REPLAY_WRAPPER_JS} ||
                  document.querySelector('.heatmap-exporter');
    if (element) {{
        const rect = element.getBoundingClientRect();
        return Math.max(rect.height, document.body.scrollHeight);
    }}
    return document.body.scrollHeight;

// Fall back to table width for insights
const tableElement = document.querySelector('table');
if (tableElement) {{
    return tableElement.offsetWidth * 1.5;
}}

return null;
